'use strict';

/* BURROW — a dig-anywhere mining adventure: tunnel through five strata, pump pests until they pop, craft, loot, and go deeper. */

const TILE = 16;
/* art23: world size is per world (old saves 240x152, new worlds 720x260) */
let W = 240;
let H = 152;
const W_OLD = 240, H_OLD = 152, W_BIG = 720, H_BIG = 420; /* art24d: new worlds 720x420 (720x260 saves still load as they are) */
let DK = 1, WK = 1;          /* depth and width scale of the loaded world vs the classic 240x152 */
/* v0.25.0: a 720x260 world that grew to 720x420 keeps its strata where they were (STRATA_H 260): the Magma just
   runs deeper and the Hollowhum fills rows 400+. STRATA_H_NEXT is set by the loader for the next setWorldSize. */
let STRATA_H = 0, STRATA_H_NEXT = 0;
function setWorldSize(w, h) {
  W = w | 0 || W_OLD; H = h | 0 || H_OLD;
  STRATA_H = (STRATA_H_NEXT | 0) > 0 && STRATA_H_NEXT < H ? STRATA_H_NEXT | 0 : H;
  DK = STRATA_H > H_OLD ? (STRATA_H - 14) / (H_OLD - 14) : 1;
  WK = W / W_OLD;
}
function dz(n) { return DK === 1 ? n : Math.round(n * DK); }
function worldBig() { return W > W_OLD || H > H_OLD; }
/* art24d: wavy strata - in deep (H >= 400) worlds each stratum boundary rolls up and down along the map,
   seeded from the world seed, so host and joiners (same seed) see the same layers. Hollowhum is the floor
   biome from row 400 down; it counts as magma for the game rules. */
const HOLLOW_Y = 400;
let SWAVE = null;
function strataWaveInit(seed) {
  if (H < HOLLOW_Y || STRATA_H < HOLLOW_Y) { SWAVE = null; return; }
  SWAVE = [1, 2, 3].map(k => {
    const a = new Int16Array(W);
    for (let x = 0; x < W; x++) a[x] = Math.round((noise1(x * 0.035, seed + 101 * k) - 0.5) * 16 + (noise1(x * 0.011, seed + 57 * k) - 0.5) * 14);
    return a;
  });
}
function swv(k, x) { return SWAVE ? SWAVE[k - 1][Math.max(0, Math.min(W - 1, x | 0))] : 0; }
function hollowAt(ty) { return H >= HOLLOW_Y + 10 && ty >= HOLLOW_Y; }
let VW = 480; /* v0.25.1: let, so the HUD can draw at a UI scale (see uiScaled) */
let VH = 270; /* v0.25.0: 270 on 16:9 screens, up to 300 on 16:10 (see setViewH) */
const SCALE = 2;
const SAVE_KEY = 'burrow_save_v2';
/* the one version number the player sees (build label, pause screen, What's new, tab title). Bump the patch number
   for small fixes (0.25.1), the minor number for feature builds (0.26.0). index.html loads the files with ?v=VERSION. */
const VERSION = '0.26.32';
const GAME_VER = 'v' + VERSION;
/* v0.25.14: air jumps: 2, +1 per Spring Boots rank (max 5); all come back on landing */
const AUTOSAVE_SECS = 30;
function airMax() { return 2 + Math.max(0, Math.min(3, (S && S.skills && S.skills.spring) | 0)); }
const PACK_HB_Y = 40, PACK_OY = 70; /* v0.25.13: the pack screen shows the hotbar as a numbered top row (1-0), the pack grid sits under it */
const SETTINGS_KEY = 'burrow_settings_v1';

const T = {
  AIR: 0, GRASS: 1, DIRT: 2, SAND: 3, STONE: 4, HARD: 5,
  BOULDER: 6, COPPER: 7, SILVER: 8, GOLD: 9, MAGMAORE: 10,
  SPIKE: 11, FIRE: 12, MAGMA: 13, BEDROCK: 14,
  CHEST_W: 15, CHEST_L: 16, CHEST_G: 17, SPRING: 18,
  SHROOM: 19, GRUBNEST: 20, POOL: 21, DRIP: 22, BRICK: 23, CHEST_R: 24,
  PACKED: 25, BEAM: 26, LADDER: 27, WBENCH: 28, FURNACE: 29, SBRICK: 30
};

const SOFT = new Set([T.GRASS, T.DIRT, T.SAND, T.FIRE]);
const ORE = new Set([T.COPPER, T.SILVER, T.GOLD, T.MAGMAORE]);
const CHEST = new Set([T.CHEST_W, T.CHEST_L, T.CHEST_G, T.CHEST_R]);
// non-solid forage / water tiles you walk through
T.LAKE = 36; /* v0.26.0: lake water (walk-through, swim, fish) */
T.CAMPF = 37; /* v0.26.12: a placed Campfire (walk-through prop, stays lit) */
const FORAGE = new Set([T.SHROOM, T.POOL, T.DRIP, T.LAKE]);
// art20: crafted props you walk through (beam still holds boulders)
const PLACED = new Set([T.BEAM, T.LADDER, T.WBENCH, T.FURNACE, T.CAMPF]);
function openTile(t) { return !t || t === T.AIR || t === T.FIRE || t === T.SPRING || t === T.SPIKE || FORAGE.has(t); }

