  if (k === 'Shift' || k === 'Control' || k === 'Alt' || k === 'Meta' || k === 'OS') return;
  if (isReservedKey(k)) { S.bindErr = 'reserved (WASD / arrows / 1-0)'; return; }
  const id = S.rebind;
