function handleSettingsUI(mx, my) {
  if (clickedBox(mx, my, 380, 14, 70, 14)) { persistSettings(); sfx('ui'); S.menu = 'pause'; S.slideDrag = null; S.rebind = null; return; }
  if (clickedBox(mx, my, 170, 96, 160, 14)) { setFullscreen(!document.fullscreenElement); sfx('ui'); }
  if (clickedBox(mx, my, 24, 114, 140, 14)) { SETTINGS.shake = !SETTINGS.shake; settingsDirty(); sfx('ui'); }
  if (clickedBox(mx, my, 170, 114, 140, 14)) { SETTINGS.showFps = !SETTINGS.showFps; settingsDirty(); sfx('ui'); }
  if (clickedBox(mx, my, 24, 132, 170, 14)) { SETTINGS.reduceFlash = !SETTINGS.reduceFlash; settingsDirty(); sfx('ui'); }
  if (clickedBox(mx, my, 24, 154, 18, 14)) { cycleDiff(-1); sfx('ui'); }
  if (clickedBox(mx, my, 200, 154, 18, 14) || clickedBox(mx, my, 46, 154, 150, 14)) { cycleDiff(1); sfx('ui'); }
  if (clickedBox(mx, my, 24, 196, 120, 18)) { sfx('ui'); S.menu = 'binds'; }
}

function handleBindsUI(mx, my) {
  if (clickedBox(mx, my, 380, 14, 70, 14)) { sfx('ui'); S.menu = 'settings'; S.rebind = null; return; }
  for (let i = 0; i < BIND_DEFS.length; i++) {
    const b = BIND_DEFS[i];
    const y = 36 + i * 12;
    if (clickedBox(mx, my, 200, y - 8, 90, 11)) {
      S.rebind = b.id;
      S.bindErr = '';
      sfx('ui');
    }
  }
  if (clickedBox(mx, my, 24, 196, 130, 16)) { resetBinds(); sfx('ui'); }
}

