function mods() {
  const m = {
    light: 0, pump: 1, speed: 1, dig: 1, stone: 1, maxHp: 0, resist: 1,
    thirstMul: 1, hungerMul: 1, ping: false, noHeat: false, contactMul: 1,
    crushMul: 1, wobble: 0, reachMul: 1, overfillLite: false, hpTick: 0, extraHeat: 0
  };
  const mix = (src) => {
    if (!src) return;
    for (const k in src) {
      if (k === 'pump' || k === 'speed' || k === 'dig' || k === 'stone' || k === 'resist' || k === 'thirstMul' || k === 'hungerMul' || k === 'contactMul' || k === 'crushMul' || k === 'reachMul')
        m[k] *= src[k];
      else if (k === 'light' || k === 'maxHp' || k === 'hpTick' || k === 'extraHeat' || k === 'wobble')
        m[k] += src[k];
      else if (k === 'ping' || k === 'noHeat' || k === 'overfillLite')
        m[k] = m[k] || src[k];
    }
  };
  if (S.p.food) mix(ITEMS[S.p.food.id].mods);
  if (S.p.drink) mix(ITEMS[S.p.drink.id].mods);
  for (const slot of ['hose', 'helm', 'boots', 'back', 'charm', 'pick', 'body']) {
    const it = S.equip[slot];
    if (it && ITEMS[it].stats) mix(ITEMS[it].stats);
  }
  if (S.p.harrierT > 0) m.speed *= 1.45;
  return m;
}

