  const c = mkCan((dim.w + EN_PAD * 2) * 2, (dim.h + EN_PAD * 2) * 2);
  const a = c.getContext('2d');
  a.scale(2, 2);
  a.translate(EN_PAD, EN_PAD);
  const fn = ENEMY_ART[kind];
  if (fn) fn(a, frame, open);
  else aBall(a, dim.w / 2, dim.h / 2, dim.w / 2, dim.h / 2, pal4('#c0a080'));
  artFinish(c, '#0c0604', enemyInk(kind), 110);
