  const changed = decorateWorld(S.tiles, S.surface, S.surfAvg, S.seed, worldAvoidRects(S.queenRoom, S.wormRoom, S.lithRoom, S.veilRoom, S.sowRoom), sx, keep);
  for (const i of changed) S.hp[i] = tileHp(S.tiles[i]);
