  give(tx * TILE + 4, ty * TILE, id, 1);
  if (rand() < 0.18 * luck()) give(tx * TILE + 4, ty * TILE, id, 1);
  floatTxt(tx * TILE, ty * TILE - 4, '+' + ITEMS[id].name, ITEMS[id].color || '#c8e0a0');
  burst(tx * TILE + 8, ty * TILE + 12, st === 'gloom' ? '#60f0b0' : st === 'magma' ? '#ff8040' : '#d8c090', 6, 22);
