  const hsp = hpM <= 7 ? 9 : Math.max(4.5, 56 / (hpM - 1)); /* v0.26.3: 8+ hearts squeeze together so they never run into the depth label */
  for (let i = 0; i < hpM; i++) drawHeart(Math.round(6 + i * hsp), 6, i < p.hp);
  drawCoinSpr(6, 15, true);
  text((p.gold | 0) + 'g', 14, 22, '#ffe080', 7);
