  text((hollowAt(ty) ? 'HOLLOWHUM' : stratumLabel(stratumAtY(ty))) + '  ' + depth + 'm', 70, 12, hollowAt(ty) ? '#b8a8ff' : '#e8dcc0', 6);
  const tease = (!uiOpen() && sleepingBossNear());
