  const hx = 10, hy = (S.stashOpen || S.mailOpen || S.nameEntry) ? -999 : VH - 22; /* art24d: the stash panel shows its own live hotbar row */
  g.fillStyle = 'rgba(32,20,10,0.62)';
  g.fillRect(hx - 3, hy - 3, 10 * 18 + 4, 22);
