  g.fillStyle = hot ? '#3a2a14' : (hov ? '#3a3020' : '#241c14');
  g.fillRect(x, y, w, h);
  g.strokeStyle = hot ? '#e6c34a' : (hov ? '#c8a050' : '#6a5030');
