  if (S.menu === 'mp' && window.NET) { NET.drawMenu(); return; }
  panelBg('PAUSED');
  drawMenuBtn(170, 48, 140, 18, 'Resume');
  drawMenuBtn(170, 70, 140, 18, 'Settings');
  drawMenuBtn(170, 92, 140, 18, 'Save');
