  drawMenuBtn(170, 158, 140, 18, 'Controls  (' + keyLabel(bindKey('help')) + ')');
  drawMenuBtn(170, 180, 140, 18, 'Crafting  (' + keyLabel(bindKey('craft')) + ')');
