  if (S.paused) return 'pause:' + (S.menu || 'pause');
  if (S.journalOpen) return 'journal';
  if (S.helpOpen) return 'help';
  if (S.shopOpen) return 'shop';
  if (S.benchOpen) return 'bench';
  if (S.craftOpen) return 'craft';
  if (S.boardOpen) return 'board';
  if (S.skillOpen) return 'skills';
  if (S.invOpen) return 'inv';
