/* v0.26.11: drop finished effects in place (no new array every frame, less garbage collection) */
function fxKeepLive(a) { let k = 0; for (let i = 0; i < a.length; i++) { const o = a[i]; if (o.t > 0) a[k++] = o; } a.length = k; return a; }
function updateFx(dt) {
  S.p.shake = Math.max(0, S.p.shake - dt);
  S.flash = Math.max(0, (S.flash || 0) - dt * 2.2);
  if (S.flash <= 0) S.flashCol = null;
  if (S.menuMsgT > 0) S.menuMsgT = Math.max(0, S.menuMsgT - dt);
  if ((S.pendingSkill || 0) > 0) {
    S.pendingSkill -= dt;
    if (S.pendingSkill <= 0) {
      if (S.winShow || S.journalOpen || S.helpOpen) S.pendingSkill = 0.05; // wait until the overlay closes
      else { S.pendingSkill = 0; S.skillOpen = true; }
    }
  }
  for (const pt of S.particles) {
    pt.t -= dt;
    pt.x += pt.vx * dt;
    pt.y += pt.vy * dt;
    pt.vy += (pt.grav != null ? pt.grav : 180) * dt;
    if (pt.kind === 'coin') pt.vx *= Math.pow(0.9, dt * 60);
  }
  fxKeepLive(S.particles);
  for (const f of S.floats) { f.t -= dt; f.y += f.vy * dt; }
  fxKeepLive(S.floats);
  if (S.fxMarks) {
    for (const m of S.fxMarks) m.t -= dt;
    fxKeepLive(S.fxMarks);
  }
}

let last = 0;
let fpsNow = 0, fpsAcc = 0, fpsFrames = 0;
function handleOverlayKeys() {
  if (S.rebind) return;
  if (S.paused) { handlePauseKey(); return; }
  if (S.craftOpen) {
    if (pressedBind('craft') || pressedBind('interact') || pressedBind('drink')) { closeCraft(); sfx('close'); return; }
    if (pressedBind('inv')) { closeCraft(); S.invOpen = true; return; }
    handleCraftKeys();
  } else if (pressedBind('craft') && !S.journalOpen && !S.helpOpen) { openCraft(); return; }
  else if (S.invOpen && pressed('Enter')) { openCraft(); return; }
  if (pressedBind('interact') && S.shopOpen) S.shopOpen = false;
  if (pressedBind('interact') && S.benchOpen) S.benchOpen = false;
  if (pressedBind('interact') && S.boardOpen) S.boardOpen = false;
  if (pressedBind('inv')) { S.invOpen = !S.invOpen && !S.shopOpen; if (S.invOpen) S.journalOpen = S.helpOpen = false; }
  if (pressedBind('skills')) S.skillOpen = false;
  if (pressedBind('journal')) {
    const was = S.journalOpen;
    S.shopOpen = S.invOpen = S.skillOpen = S.benchOpen = S.craftOpen = S.boardOpen = S.helpOpen = false;
    S.journalOpen = !was;
  } else if (pressedBind('help') || pressed('F1')) {
    const was = S.helpOpen;
    S.shopOpen = S.invOpen = S.skillOpen = S.benchOpen = S.craftOpen = S.boardOpen = S.journalOpen = false;
    S.helpOpen = !was;
  }
  if (pressedBind('pause') || pressed('Escape')) {
    S.shopOpen = S.invOpen = S.skillOpen = S.benchOpen = S.craftOpen = S.boardOpen = S.journalOpen = S.helpOpen = false;
  }
}
function loop(ts) {
  const raw = Math.min(0.05, (ts - last) / 1000 || 0.016);
  last = ts;
  if (!S) { requestAnimationFrame(loop); return; }
  pollGamepad();
  let dt = raw;
  if ((S.slowT || 0) > 0) {
    S.slowT -= raw;
    dt = raw * 0.38;
  }
  S.time += raw;
  try { dnTick(raw); } catch (e) {}   /* v0.26.22: day/night clock */
  fpsFrames++;
  fpsAcc += raw;
  if (fpsAcc >= 0.4) { fpsNow = Math.round(fpsFrames / fpsAcc); fpsFrames = 0; fpsAcc = 0; }
  tickMusic(raw);
  const frozen = (S.hitStop || 0) > 0;
  if (frozen) { S.hitStop -= raw; dt = 0; }
  if (!S.paused && !S.winShow) S.stats.playT += raw;
  if (S.p.dead) S.p.deadT = (S.p.deadT || 0) + raw;
  if (S.winShow) S.winT = (S.winT || 0) + raw;
  if (!S.p.dead && !uiOpen()) {
    if (!frozen) {
      updatePlayer(dt);
      updateEnemies(dt);
      updateFalling(dt);
      updatePickups(dt);
    }
    if (padJust._slotPrev) S.selected = (S.selected + 9) % 10;
    if (padJust._slotNext) S.selected = (S.selected + 1) % 10;
  } else {
    if (!S.p.dead && !S.winShow) handleOverlayKeys();
    if (window.NET && NET.live() && !frozen) { updateEnemies(dt); updateFalling(dt); updatePickups(dt); }
  }
  if (window.NET) NET.tick(raw);
  updateFlyers(frozen ? 0 : dt);
  art22Tick(raw, dt);
  tutTick();
  S._goalT = (S._goalT || 0) + raw;
  if (S._goalT > 0.5 && !S.p.dead) { S._goalT = 0; checkGoals(); }
  if ((S.winPending || 0) > 0) { S.winPending -= raw; if (S.winPending <= 0 && !S.p.dead) openWin(); }
  updateToasts(raw);
  panelAnimBegin(raw);
  S._frameNo = (S._frameNo | 0) + 1;
  handleUI();
  updateFx(dt);
  drawGame();
  hoverTick();
  S.saveT += raw;
  if (S.saveT > AUTOSAVE_SECS) { S.saveT = 0; saveGame(); }   /* v0.26.18: every 30s (was 8s); leave/hide/sleep/manual saves are separate */
  mouse.clicked = false;
  mouse.right = false;
  mouse.wheel = 0;
  for (const k in just) just[k] = false;
  clearPadJust();
  requestAnimationFrame(loop);
}

