interactE = function () {
  const pcx = S.p.x + S.p.w / 2, dx = r => r ? Math.abs(r.x + r.w / 2 - pcx) : 1e9;
  const mine = [];
  if (nearWell()) mine.push(['well', dx(S.well)]);
  if (nearStash()) mine.push(['stash', dx(baseRects().stash)]);
  if (nearBed()) mine.push(['bed', dx(baseRects().bed)]);
  if (mine.length) {
    mine.sort((a, b) => a[1] - b[1]);
    let other = 1e9;
    if (nearWick()) other = Math.min(other, dx(S.shop));
    if (nearBench()) other = Math.min(other, dx(S.bench));
    if (nearBoard()) other = Math.min(other, dx(boardRect()));
    if (mine[0][1] <= other) {
      const k = mine[0][0];
      if (k === 'well') return useWell();
      if (k === 'stash') { S.stashOpen = true; S.shopOpen = S.boardOpen = S.invOpen = S.craftOpen = false; sfx('open'); return; }
      if (k === 'bed') return useBed();
    }
  }
  return _a22interactE();
};
