function boot() {
  buildTiles();
  loadSettingsBlob();
  applyAudioGains();
  const fresh = typeof location !== 'undefined' && /[?&]fresh=1/.test(location.search);
  SAVE_INFO.bootLoaded = !fresh && loadGame();
  if (!SAVE_INFO.bootLoaded) newGame();
  else if (S) {
    if (SAVE_INFO.fromBak) { toast('Save was damaged', 'loaded the backup from a moment earlier', '#e0c060', 'ui'); try { saveGame(); } catch (err) {} }
    else toast('Welcome back', 'progress loaded', '#80e080', 'ui');
  }
  if (S) S.shopOpen = S.benchOpen = S.craftOpen = S.invOpen = S.skillOpen = S.boardOpen = S.journalOpen = S.helpOpen = false;
  if (SETTINGS.fullscreen) {
    try { setFullscreen(true); } catch (err) {}
  }
  requestAnimationFrame(loop);
}
if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot);
else boot();

if (typeof location !== 'undefined' && /[?&]fxdemo=1/.test(location.search)) {
  setTimeout(() => {
    newGame();
    if (!S || !S.p) return;
    S.shopOpen = S.invOpen = S.skillOpen = S.benchOpen = S.craftOpen = S.boardOpen = S.journalOpen = S.helpOpen = S.paused = false;
    S.p.iFrames = 30;
    S._demoLock = true;
    placeOnSurface(Math.floor((S.p.x + 5) / TILE));
    const steps = [
      () => eatOrDrink('mite_lunch', false),
      () => eatOrDrink('well_water', true),
      () => window.BURROW.juice('pop'),
      () => window.BURROW.juice('level'),
      () => window.BURROW.juice('chest'),
      () => window.BURROW.juice('ore'),
      () => window.BURROW.juice('gold'),
      () => window.BURROW.juice('boss'),
      () => window.BURROW.juice('buff'),
      () => window.BURROW.juice('crush')
    ];
    let i = 0;
    const run = () => {
      if (i >= steps.length) return;
      steps[i++]();
      setTimeout(run, 800);
    };
    setTimeout(run, 400);
  }, 350);
}

if (typeof location !== 'undefined' && /[?&]debug=1/.test(location.search)) {
  const dbg = document.createElement('pre');
  dbg.id = 'burrow-debug';
  dbg.style.cssText = 'position:fixed;left:8px;bottom:8px;z-index:9;background:#000c;color:#9f8;font:11px monospace;padding:6px;max-width:460px;white-space:pre-wrap';
  document.body.appendChild(dbg);
  setInterval(() => { try { dbg.textContent = JSON.stringify(window.BURROW.snap(), null, 0); } catch (err) {} }, 200);
}

