    const tx = Math.floor((S.p.x + S.p.w * 0.5) / TILE);
    const gy = localSurf(tx);
    for (let y = gy; y <= gy + depth; y++) {
      if (tget(tx, y) !== T.BEDROCK) tset(tx, y, T.AIR);
      if (tget(tx + 1, y) !== T.BEDROCK) tset(tx + 1, y, T.AIR);
    }
    S.p.x = tx * TILE + Math.floor((TILE - S.p.w) / 2);
    S.p.y = (gy + depth) * TILE - S.p.h;
    S.p.vy = 0;
    S.p.grounded = true;
    cam();
