/* ---------- art24d: walk-up prompts never cover the miner or pests ----------
   Chazz was fighting a mite hidden behind a Chest plate (the pump bracket drew over the plate, so it looked garbled).
   While any pest is within 8 tiles, or you are pumping, prompts shrink to a faint name tag that also dodges you and
   pests (or hide). Otherwise the plate picks the first free spot: above the thing, above the miner, below, the sides. */
const A24D_THREAT_R = 8 * TILE;
function a24dThreat() {
  const p = S.p; if (!p || p.dead) return false;
  if (p.pumping && p.pumpTgt && !p.pumpTgt.dead) return true;
  const cx = p.x + p.w / 2, cy = p.y + p.h / 2;
  for (const e of S.enemies || []) {
    if (!e || e.dead) continue;
    if (Math.abs(e.x + (e.w || 12) / 2 - cx) < A24D_THREAT_R && Math.abs(e.y + (e.h || 10) / 2 - cy) < A24D_THREAT_R) return true;
  }
  return false;
}
function a24dAvoidRects() {
  const p = S.p, L = [];
  if (p) L.push({ x: p.x - S.camX - 4, y: p.y - S.camY - 5, w: p.w + 8, h: p.h + 7 });
  if (S._fsF === (S._frameNo | 0) && S._fixedSigns) for (const r of S._fixedSigns) L.push(r);
  for (const e of S.enemies || []) {
    if (!e || e.dead) continue;
    const x = e.x - S.camX, y = e.y - S.camY, w = e.w || 12, h = e.h || 10;
    if (x + w < -8 || x > VW + 8 || y + h < -8 || y > VH + 8) continue;
    const pad = 3 + Math.min(6, (e.swell || 0) * 6);
    L.push({ x: x - pad, y: y - pad, w: w + pad * 2, h: h + pad * 2 });
  }
  return L;
}
function a24dHitsAny(x, y, w, h, L) {
  for (const r of L) if (x < r.x + r.w && x + w > r.x && y < r.y + r.h && y + h > r.y) return true;
  return false;
}
function a24dPlateSpots(o, sx, w, h, slide) {
  const p = S.p, mx = p.x - S.camX, my = p.y - S.camY;
  const oy = o.r.y - S.camY, ob = o.r.y + o.r.h - S.camY;
  const raw = [
    [sx - w / 2, oy - h - 5 + slide],
    [mx + p.w / 2 - w / 2, my - h - 9 + slide],
    [sx - w / 2, ob + 4 + slide],
    [mx + p.w + 7, my + p.h / 2 - h / 2],
    [mx - w - 7, my + p.h / 2 - h / 2],
    [mx + p.w / 2 - w / 2, my + p.h + 5]
  ];
  return raw.map(([x, y]) => ({ x: Math.round(clamp(x, 2, VW - w - 2)), y: Math.round(clamp(y, 2, VH - h - 30)) }));
}
function a24dTinyTag(o, sx, a, L) {
  boldFont(6, '#fff');
  const tw = Math.ceil(g.measureText(o.name).width) + 4, th = 8;
  const oy = o.r.y - S.camY, ob = o.r.y + o.r.h - S.camY;
  const spots = [[sx - tw / 2, oy - th - 2], [sx - tw / 2, ob + 2], [o.r.x - S.camX - tw - 2, oy + o.r.h / 2 - th / 2], [o.r.x + o.r.w - S.camX + 2, oy + o.r.h / 2 - th / 2]];
  for (const [x0, y0] of spots) {
    const x = Math.round(clamp(x0, 2, VW - tw - 2)), y = Math.round(clamp(y0, 2, VH - th - 30));
    if (a24dHitsAny(x, y, tw, th, L)) continue;
    g.globalAlpha = a * 0.75;
    g.fillStyle = 'rgba(12,8,5,0.6)'; g.fillRect(x, y, tw, th);
    g.globalAlpha = a * 0.85;
    textOutlined(o.name, x + 2, y + 6, '#e8dcc0', 6);
    g.globalAlpha = 1;
    if (a > 0.3) S._tagR = { x, y, w: tw, h: th };
    return;
  }
}
/* big walk-up cards (board, bench, shop, stations): if the card would land on the miner or a pest, lift it above
   the miner, else drop it below */
function a24dCardY(x, y, w, h) {
  const L = a24dAvoidRects();
  if (!a24dHitsAny(x, y, w, h, L)) return y;
  const p = S.p, my = p.y - S.camY;
  const up = Math.round(my - h - 9);
  if (up >= 2 && !a24dHitsAny(x, up, w, h, L)) return up;
  const dn = Math.round(my + p.h + 5);
  if (dn + h <= VH - 30 && !a24dHitsAny(x, dn, w, h, L)) return dn;
  return Math.max(2, up);
}

/* ===================== art24d: no more small world =====================
   Old 240x152 saves are upgraded to the big world the moment they load (no prompt, no menu entry).
   Everything about the player comes along; the pre-upgrade save is kept in localStorage
   (burrow_save_v2_preupgrade + burrow_save_v2_small) and serve.py keeps the old file in saves/old/. */
function a24dUpgradeSmall() {
  if (worldBig() || !S || !S.p) return false;
  const oldD = buildSaveData();
  const oldJson = JSON.stringify(oldD);
  try { localStorage.setItem(SAVE_KEY + '_preupgrade', oldJson); } catch (err) { console.warn('pre-upgrade backup did not fit', err); }
  try { localStorage.setItem(SAVE_KEY + '_small', oldJson); } catch (err) {}
  const K = {
    p: S.p, skills: S.skills, inv: S.inv, packSize: S.packSize, equip: S.equip, packBought: S.packBought,
    relics: S.relics, goals: S.goals, stats: S.stats, stash: S.stash, stashSize: S.stashSize, craft: S.craft, tut: S.tut,
    magmaUnlocked: S.magmaUnlocked, bossesKilled: S.bossesKilled, bounties: S.bounties, time: S.time
  };
  const oldW = W;
  newGame(null, [W_BIG, H_BIG]);
  S.charSel = null; /* same miner, no character screen */
  const np = S.p;
  const mark = K.p.retMark;
  S.p = Object.assign({}, K.p, {
    x: np.x, y: np.y, vx: 0, vy: 0, grounded: true, dead: false, deadT: 0, iFrames: 2.4, pumpTgt: null, dig: null,
    depthBest: Math.round((K.p.depthBest || 0) * DK),
    /* the Joint mark points into the old map, so it cannot be kept; the Bong would refuse it anyway */
    retMark: null
  });
  if (typeof sanitizeLoadedPlayer === 'function') { try { sanitizeLoadedPlayer(); } catch (err) {} }
  Object.assign(S, { skills: K.skills, inv: K.inv, packSize: K.packSize, equip: K.equip, packBought: K.packBought,
    relics: K.relics || {}, stats: K.stats, stash: K.stash || S.stash, craft: K.craft, tut: K.tut, magmaUnlocked: !!K.magmaUnlocked });
  if (K.stashSize) S.stashSize = K.stashSize;
  if (K.bossesKilled != null) S.bossesKilled = K.bossesKilled;
  if (K.bounties) S.bounties = K.bounties;
  if (K.time != null) S.time = K.time;
  if (K.goals) S.goals = { done: K.goals.done || {}, won: !!K.goals.won, silent: false };
  ensureCraft(S);
  if (typeof stashFit === 'function') { try { stashFit(); } catch (err) {} }
  S.sizeAsk = false; S.sizeAsked = true;
  fogLoad(null);
  cam();
  saveGame();
  S._a24dUpgraded = { from: oldW, mark: !!mark };
  /* push the upgraded world to serve.py's saves/ right away (it keeps the small one in saves/old/) */
  if (window.NET && NET.diskPush) for (const t of [600, 2500]) setTimeout(() => { try { NET.diskPush(true); } catch (err) {} }, t);
  toast('Your world got bigger', 'level, pack, stash, gold and journal came along' + (mark ? ' - Joint mark reset' : ''), '#80e080', 'ui');
  return true;
}


/* ===================== art24d: Left-click to mine really means click-only =====================
   Cause: with the toggle on, walking into a block still dug, because the collision code in
   moveAxisResolve (and holdDig) calls tryDig on contact. Now, while Left-click to mine is on, any dig
   that comes from movement is ignored; only an aimed dig goes through: a mouse click/hold on a tile,
   or on a gamepad the right stick (push it toward the block). Off (the default) = exactly as before.
   Charge is its own skill action and is untouched; Bore still widens aimed side digs. */
function a24dClickOnly() { return !!(SETTINGS && SETTINGS.clickMine); }
const _a24dTryDig = tryDig;
tryDig = function (tx, ty, dt, m, boreUp) {
  if (S && S._a24dMoveDig && !S._a24dAim && a24dClickOnly()) return;
  return _a24dTryDig.apply(this, arguments);
};
const _a24dMAR = moveAxisResolve;
moveAxisResolve = function () {
  const was = S._a24dMoveDig; S._a24dMoveDig = true;
  try { return _a24dMAR.apply(this, arguments); } finally { S._a24dMoveDig = was; }
};
/* right stick on a gamepad = aimed dig when click-mining is on (the pad has no cursor) */
function a24dPadAim() {
  let gp = null;
  try { const pads = navigator.getGamepads ? navigator.getGamepads() : null; if (pads) gp = (padIndex >= 0 && pads[padIndex]) || Array.from(pads).find(q => q && q.connected) || null; } catch (err) { gp = null; }
  if (S._padAimTest) return S._padAimTest; /* tests */
  if (!gp || !gp.axes || gp.axes.length < 4) return null;
  const x = gp.axes[2] || 0, y = gp.axes[3] || 0;
  if (Math.hypot(x, y) < 0.5) return null;
  return Math.abs(x) >= Math.abs(y) ? { x: Math.sign(x), y: 0 } : { x: 0, y: Math.sign(y) };
}
const _a24dHoldDig = holdDig;
holdDig = function (p, ax, dt, m, phantom) {
  if (a24dClickOnly()) {
    const aim = a24dPadAim();
    if (aim && !uiOpen()) {
      let tx, ty, bore = false;
      if (aim.x) { tx = aim.x > 0 ? Math.floor((p.x + p.w + 1) / TILE) : Math.floor((p.x - 1) / TILE); ty = Math.floor((p.y + p.h * 0.55) / TILE); bore = !!skill('bore'); p.face = aim.x; }
      else if (aim.y > 0 && p.grounded) { tx = Math.floor((p.x + p.w * 0.5) / TILE); ty = Math.floor((p.y + p.h + 1) / TILE); }
      else if (aim.y < 0 && (p.grounded || p.onRope || p.vy <= 0)) { tx = Math.floor((p.x + p.w * 0.5) / TILE); ty = Math.floor((p.y - 1) / TILE); }
      if (tx != null && isDiggable(tget(tx, ty)) && tget(tx, ty) !== T.BEDROCK) {
        S._a24dAim = true;
        try { tryDig(tx, ty, dt, m, bore); } finally { S._a24dAim = false; }
        return;
      }
    }
  }
  const was = S._a24dMoveDig; S._a24dMoveDig = true;
  try { return _a24dHoldDig.apply(this, arguments); } finally { S._a24dMoveDig = was; }
};

/* the same toggle right on the main pause screen (synced with Settings, saved to burrow_settings_v1) */
