  if (L.att && !L.claimed) { sfx('deny'); floatTxt(S.p.x, S.p.y - 8, 'claim it first', '#c07070', { sz: 6 }); return; }
  M.letters.splice(i, 1); S._mailSel = clamp(i, 0, Math.max(0, M.letters.length - 1)); S._mailScroll = 0;
