    text('From: ' + fitText(q.from, vw - 40, 6), vx + 6, y, '#6a4a2a', 6); y += 4;
    g.fillStyle = 'rgba(90,60,30,0.4)'; g.fillRect(vx + 6, y, vw - 12, 1); y += 9;
    const lines = mailBodyLines(q), room = Math.floor((vy + vh - (q.att ? 22 : 12) - y) / 9);
    const maxS = Math.max(0, lines.length - room); S._mailScroll = clamp(S._mailScroll | 0, 0, maxS); S._mailMaxS = maxS;
    const shown = lines.slice(S._mailScroll, S._mailScroll + room);
