    if (maxS > 0) { text(S._mailScroll > 0 ? '^' : ' ', vx + vw - 10, vy + 46, '#8a5a30', 7); text(S._mailScroll < maxS ? 'v' : ' ', vx + vw - 10, vy + vh - (q.att ? 22 : 6), '#8a5a30', 7); if (!q.att) text('wheel / W S scroll', vx + vw - 78, vy + vh - 3, '#8a6a40', 6); }
