  aL(a, ox + 2.5 * s, oy + 11.5 * s, ox + 10.5 * s, oy + 3.5 * s, 1.1 * s, '#b8bec8');
  aE(a, ox + 11.5 * s, oy + 2.5 * s, 2.6 * s, 2.6 * s, '#8a4a20'); aE(a, ox + 11.5 * s, oy + 2.5 * s, 1.8 * s, 1.8 * s, '#d8803a'); aE(a, ox + 11 * s, oy + 2 * s, 0.7 * s, 0.7 * s, '#ffd0a0');
