  const near = (S.enemies || []).some(e => !e.dead && Math.abs(e.x - p.x) < 90 && Math.abs(e.y - p.y) < 70);
  const pl = (typeof plate !== 'undefined' && plate.o && plate.a > 0.3 && !platesHidden()) ? plate.o : null;
  if (pl) add(capFor('interact'), (pl.acts && pl.acts[0] && pl.acts[0][1]) || 'use', true);
  add(capFor('pump'), 'pump', near);
  const s = S.inv && S.inv[S.selected], it = s && ITEMS[s.id];
  if (it && quickUsable(s) && !quickGuard(s)) add(pad ? capFor('use') : String((S.selected + 1) % 10), it.name.length > 12 ? 'use' : it.name.toLowerCase(), false);
  if (p.hunger != null && p.hunger < 45) add(capFor('eat'), 'eat', p.hunger < 20);
  if (p.thirst != null && p.thirst < thirstCap() * 0.45) add(capFor('drink'), 'drink', p.thirst < thirstCap() * 0.2);
  add(pad ? 'STICK' : 'WASD', 'dig', false);
