      const R = (c, r) => ({ x: (v.x + 1 + c) * TILE, y: (v.y + 1 + r) * TILE, w: 16, h: 16 });
      const acts = v.open ? [['', 'opened']] : v.kind === 'boulder' ? [[moveCap('A/D'), 'push'], [E + ' x2', 'reset']] : v.kind === 'beam' ? [[E, 'turn'], ['CLICK', 'turn']] : [['DIG', 'channel'], [E, 'sluice']];
      L.push({ k: 'pv' + i, name: PV_NAME[v.kind], acts, r: { x: v.x * TILE, y: (v.y + 1) * TILE, w: 16, h: d.rh * TILE }, range: 26 });
      if (v.open) return;
