const UPDP_BTN = { x: 184, y: 14, w: 104, h: 14 };
function updPauseOn() { return updOn() && S && S.paused && S.menu === 'pause' && !S.quitAsk && !S.notesOpen && !S.whatsNew && !S.lootLogOpen; }
