  text(kinds + '/' + FISH_IDS.length + ' kinds   ' + fishLogTotal() + ' caught', 112, 24, '#a09080', 6);
  const where = { cave_minnow: 'any water, shallow', mud_carp: 'shallow lakes', pebble_loach: 'shallow, near the top', stone_perch: 'deeper water',
    blind_cavefish: 'deep, dark water', glowfish: 'the Gloom', lava_eel: 'hot water by magma', ghost_pike: 'deep Gloom, rare', crystal_koi: 'rare, anywhere deep' };
  const BIG = S.p.fishBig || {};
