    text(n ? 'caught ' + n + (BIG[id] ? '  best ' + BIG[id] + ' cm' : '') : 'not caught yet', x + 40, y + 24, '#e8dcc0', 6);
    text(where[id], x + 40, y + 33, '#a09080', 6);
