  BurrowDisplay.state = () => ({ res: 'auto', preset: RES_PRESETS[0], screenMode: SETTINGS.screenMode || 'fit', fullscreen: !!NFS, windowMode: 'windowed', fsNative: true, view: [VW, VH] });
